head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > tooltipPositionY]<br/>tooltipDisplay=true 일때 툴팁이 표시될 Y 좌표 오프셋을 설정합니다.",
    "validation" : [
        "미설정 시, '3+cellHeight' 로 적용됩니다.",
        "Number 설정 시, Cell 의 top 좌표를 기준으로 Y 좌표 오프셋 위치를 픽셀(px) 단위 숫자로 설정합니다. (음수 설정 가능)",
        "String 설정 시, Cell 의 height 를 사용한 계산식으로 Y 좌표 오프셋 위치를 설정합니다.",
        "String 설정 시, Cell 의 top 좌표를 기준으로 계산되며 'cellHeight'(Cell 의 height)와 'cellWidth'(Cell 의 width) 변수를 사용할 수 있습니다.",
        "Header, Body, Footer 등 전체 GridView 영역의 Cell 에 적용되며 Cell 값이 ''(Empty String)인 경우에는 툴팁이 표시되지 않습니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // con_tooltipPositionY 초기값 보관 (미설정='3+cellHeight' 케이스로 시작)
    scwin.gVar = { "cTooltipPositionY": "" };

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
//  - tooltipPositionY 검증용 커스텀 GridView 를 인라인 정의로 생성한다.
//    (Y 오프셋이 툴팁 표시 좌표에 미치는 차이를 좌표 측정으로 확인하기 위해 잘린 긴 값 + 빈값 Cell 구성)
//  - 고정 전제 : tooltipDisplay=true (Y 오프셋은 tooltipDisplay=true 일때만 의미)
//  - col_long : 긴 값(잘림) text  -> 마우스오버 시 툴팁 표시(좌표 측정 대상)
//    col_empty: 빈 값('') text    -> 값이 빈문자열이라 툴팁 미표시(@spec)
//  - tooltipPositionY 는 con 값에 따라 미설정(='3+cellHeight') / 양수(80) / 음수(-30) / String 계산식(cellHeight+10) 으로 변경
scwin.comp_init = async function () {
    // con 현재값 반영 (Target 재생성 버튼이 comp_init 재호출)
    scwin.gVar.cTooltipPositionY = con_tooltipPositionY.getValue();   // "" / "80" / "-30" / "cellHeight+10"

    // 동적 생성용 네임스페이스 (페이지 scope 에서 공통 strNameSpace 가 비어있을 수 있어 로컬 정의)
    let ns = 'xmlns="http://www.w3.org/1999/xhtml" xmlns:ev="http://www.w3.org/2001/xml-events" xmlns:w2="http://www.inswave.com/websquare" xmlns:xf="http://www.w3.org/2002/xforms"';

    // 기존 target / dataList 정리
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 안내 라벨 (가장 먼저 생성)
    let posMsg = (scwin.gVar.cTooltipPositionY === "") ? "미설정(기본 3+cellHeight)" : scwin.gVar.cTooltipPositionY;
    $c.gcm.createLabel('label="[전제] tooltipDisplay=true 고정. tooltipPositionY=' + posMsg + '.\n[전제] col_long 은 좁은 폭에 긴 값이라 잘림 -> 마우스오버 시 Body/Footer/Header Cell 에 툴팁 표시. col_empty 는 값이 빈문자열이라 미표시.\n[절차] 잘린 Cell(col_long Body/Footer, Header) 에 마우스를 오버하여 툴팁을 표시한 뒤 그 Cell 을 클릭하면, 툴팁의 실제 Y 오프셋(실측)이 return 영역에 함께 출력됩니다.\n[확인] 미설정=3+cellHeight 기준 대비 양수(80)는 더 아래, 음수(-30)는 더 위, String(cellHeight+10)은 Cell 높이+10 만큼 아래에 표시. 실측 Y오프셋이 설정값과 일치하는지 확인하세요. 빈값 Cell 은 미표시."', '', 'label1');

    // dataList 생성 ($p.dynamicCreate 가 아닌 $p.data.create 로 생성)
    let dlt = '<w2:dataList ' + ns + ' baseNode="list" id="dlt_bind" repeatNode="map">';
    dlt += '<w2:columnInfo>';
    dlt += '<w2:column dataType="text" id="col_long" name="col_long"></w2:column>';
    dlt += '<w2:column dataType="text" id="col_empty" name="col_empty"></w2:column>';
    dlt += '</w2:columnInfo>';
    dlt += '<w2:data use="true"></w2:data>';
    dlt += '</w2:dataList>';
    $p.data.create(dlt);
    let arrDC = $p.data.getAllDataCollection("object");
    scwin.dlt_bind = arrDC[arrDC.length - 1];
    scwin.dlt_bind.setJSON([
        { "col_long": "서울특별시 강남구 테헤란로 152 강남파이낸스센터 23층", "col_empty": "" },
        { "col_long": "부산광역시 해운대구 센텀중앙로 79 센텀사이언스파크 18층", "col_empty": "" }
    ], false);

    // tooltipPositionY : con 값에 따라 설정/미설정 (미설정 시 속성 자체를 제외하여 기본값 '3+cellHeight' 동작 확인)
    let posAttr = (scwin.gVar.cTooltipPositionY === "") ? "" : 'tooltipPositionY="' + scwin.gVar.cTooltipPositionY + '" ';

    // 커스텀 GridView 인라인 정의
    //  - col_long : 좁은 폭(80) 에 긴 값을 넣어 잘림(truncation) 유도 -> 툴팁 표시 대상
    //  - col_empty: 빈 값 Column (@spec : 빈문자열 미표시)
    //  - Header/Footer 에도 긴 값을 두어 전체 영역 Cell 적용 확인
    let strTarget = '<w2:gridView ' + ns + ' ' + posAttr + 'tooltipDisplay="true" checkAllType="false" dataList="data:dlt_bind" id="" style="width:360px;height:220px;">';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="80" inputType="text" id="col_long" value="배송지 주소 (전체 표기시 잘림 발생)"></w2:column>';
    strTarget += '<w2:column width="80" inputType="text" id="col_empty" value="비고"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="80" inputType="text" id="col_long" dataList="col_long"></w2:column>';
    strTarget += '<w2:column width="80" inputType="text" id="col_empty" dataList="col_empty"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '<w2:footer style="" id="footer1">';
    strTarget += '<w2:row style="" id="frow1">';
    strTarget += '<w2:column width="80" inputType="text" id="ft_long" value="합계 1,234,567,890 원 (전 영업점 기준)"></w2:column>';
    strTarget += '<w2:column width="80" inputType="text" id="ft_empty" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:footer>';
    strTarget += '</w2:gridView>';

    let grp_comp = document.querySelector('.tc_group_basic');
    scwin.target1 = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);

    // 클릭 시 현재 표시된 툴팁 정보를 return 영역에 출력하기 위한 클릭 리스너 설치
    scwin.attachTooltipClick();

    // Y 오프셋 결정성 보장 : 페이지 하단에 충분한 여백을 두어 엔진의 "위로 뒤집기(flip)" 회피
    scwin.ensureTooltipRoom();
}



// 엔진은 셀 하단에 툴팁을 펼칠 공간이 없으면(tooltip.offsetTop + offsetHeight + 20 > body.scrollHeight)
// 툴팁을 셀 위로 뒤집어 표시한다. 뒤집히면 top 이 (cellTop - tooltipHeight) 로 재설정되어
// 설정한 Y 오프셋 정보가 소실되므로 측정이 비결정적이 된다.
// 본 함수는 페이지 하단에 고정 높이의 spacer 를 두어 측정 대상 셀이 항상 아래로 펼쳐지도록 보장한다.
// (spacer 는 레이아웃 하단 여백일 뿐 좌표 측정값에는 영향을 주지 않는다.)
scwin.ensureTooltipRoom = function () {
    let sp = document.getElementById("__tooltipPosY_room");
    if (!sp) {
        sp = document.createElement("div");
        sp.id = "__tooltipPosY_room";
        sp.style.height = "600px";
        sp.style.width = "1px";
        sp.setAttribute("aria-hidden", "true");
        document.body.appendChild(sp);
    }
};



// Header/Body/Footer Cell 클릭 시 "현재 표시된" 툴팁 정보를 return 영역에 출력
//  - 셀에 마우스를 오버해 툴팁이 표시된 상태에서 그 영역을 클릭하면 호출된다.
//  - 타이밍 주의 : 엔진은 클릭의 기본/버블 처리 단계에서 hover 툴팁을 닫는다(display:none).
//    따라서 클릭의 "캡처(capture) 단계" 리스너로 잡아야 툴팁이 아직 살아있어
//    $c.gcm.getTooltipInfo 가 textContent/display 를 정상 출력한다.
//  - 마우스오버만 해서는 출력되지 않으며, 클릭 시점에 현재 hover 로 표시된 툴팁 값이 캡처된다.
scwin.attachTooltipClick = function () {
    let gridEl = scwin.target1.getElement ? scwin.target1.getElement() : document.getElementById(scwin.target1.getID());
    if (!gridEl) { return; }
    if (scwin.tooltipClickFn && scwin.tooltipClickEl) {
        scwin.tooltipClickEl.removeEventListener("click", scwin.tooltipClickFn, true);
    }
    scwin.tooltipClickFn = function (e) {
        $c.gcm.getTooltipInfo(wf_body_bottom);
        // 클릭 시점에 표시된 툴팁 엘리먼트의 위치와 클릭한 셀의 위치를 "레이아웃(문서) 좌표"로
        // 측정해 적용된 Y 오프셋(설정값 대비 실측)을 return 영역에 한 줄 출력한다.
        //  - 비결정성 회피 : 뷰포트 상대 좌표(getBoundingClientRect)는 스크롤/창크기/클릭지점에
        //    따라 흔들리므로 사용하지 않는다.
        //  - 결정적 기준계 : 엔진은 툴팁 표시 시
        //      top = WebSquare.style.getAbsoluteTop(cell) + tooltipPositionY
        //    로 인라인 style.top 을 설정한다(eventController showTooltip).
        //    getAbsoluteTop = getBoundingClientRect().top + scrollTop 이므로 문서 기준 좌표라
        //    스크롤/뷰포트와 무관(불변)하다. 따라서
        //      offsetY = round(parseFloat(tip.style.top) - getAbsoluteTop(cell))
        //    는 설정값과 정확히 일치하며 같은 셀/같은 config 면 반복해도 동일 정수다.
        //  - 단, 엔진은 셀 하단에 툴팁 펼칠 공간이 없으면 위로 뒤집어(flip) top 을 재설정한다.
        //    flip 되면 Y 오프셋 정보가 사라지므로, comp_init 에서 페이지 하단에 충분한 여백
        //    (scwin.ensureTooltipRoom 의 spacer)을 두어 본 샘플의 측정 셀이 항상 아래로 펼쳐지게 한다.
        let tip = null;
        let tips = document.querySelectorAll('[class*="_tooltip"]');
        for (let i = 0; i < tips.length; i++) {
            let st = window.getComputedStyle(tips[i]);
            if (st.display !== "none" && st.visibility !== "hidden" && tips[i].offsetHeight > 0) {
                tip = tips[i];
                break;
            }
        }
        if (!tip) { return; }
        let cell = (e && e.target && e.target.closest) ? (e.target.closest("td") || e.target) : null;
        if (!cell) { return; }
        // 엔진이 설정한 인라인 style.top(문서 기준) - 셀의 문서 기준 top
        let tipTop = parseFloat(tip.style.top);
        let cellTop = WebSquare.style.getAbsoluteTop(cell);
        let offsetY = Math.round(tipTop - cellTop);
        wf_body_bottom.getObj("scwin").setReturnValue("툴팁 Y오프셋(실측): " + offsetY + "px");
    };
    scwin.tooltipClickEl = gridEl;
    gridEl.addEventListener("click", scwin.tooltipClickFn, true);
};
